import sys

def is_valid_sudoku_brute(board):
    for i in range(9):
        seen = set()
        for j in range(9):
            if board[i][j] != '.':
                if board[i][j] in seen:
                    return False
                seen.add(board[i][j])
    for j in range(9):
        seen = set()
        for i in range(9):
            if board[i][j] != '.':
                if board[i][j] in seen:
                    return False
                seen.add(board[i][j])
    for bi in range(3):
        for bj in range(3):
            seen = set()
            for i in range(bi * 3, bi * 3 + 3):
                for j in range(bj * 3, bj * 3 + 3):
                    if board[i][j] != '.':
                        if board[i][j] in seen:
                            return False
                        seen.add(board[i][j])
    return True

