import sys

def is_valid_sudoku_opt(board):
    seen = set()
    for i in range(9):
        for j in range(9):
            v = board[i][j]
            if v == '.':
                continue
            if (i, v) in seen or (v, j) in seen or (i // 3, j // 3, v) in seen:
                return False
            seen.add((i, v))
            seen.add((v, j))
            seen.add((i // 3, j // 3, v))
    return True

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    board = []
    idx = 1
    for _ in range(n):
        board.append(data[idx:idx + n])
        idx += n
    print('true' if is_valid_sudoku_opt(board) else 'false')
